namespace sv_85d58397bf1b4bfc875d87985ecfae63.Services;

/// <summary>
/// Scoped service (one per circuit) that holds the currently selected warehouse
/// and notifies subscribers when it changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<Warehouse> AvailableWarehouses =
    [
        new("wh-a", "Warehouse A"),
        new("wh-b", "Warehouse B"),
        new("wh-c", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }
}

public sealed record Warehouse(string Id, string Name);

namespace sv_85d58397bf1b4bfc875d87985ecfae63.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers
/// when new data arrives. Each circuit (user) gets its own independent instance.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling retrieves updated alert data.
    /// All subscribed components should re-render.
    /// </summary>
    public event Func<Task>? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(Random.Shared.Next(0, 16));
    }

    /// <summary>
    /// Call when a component becomes visible and wants polling to run.
    /// Polling starts on the first subscriber and stops when the last unsubscribes.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    /// <summary>
    /// Call when a component is disposed or hidden.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _cts?.Cancel();
                _timer?.Dispose();
                _timer = null;
                _cts?.Dispose();
                _cts = null;
            }
        }
    }

    /// <summary>
    /// Triggers an immediate refresh (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshNowAsync()
    {
        await FetchAndNotifyAsync();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await FetchAndNotifyAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);

        if (OnAlertDataChanged is not null)
        {
            await OnAlertDataChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

