@using sv_85d58397bf1b4bfc875d87985ecfae63.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChangedAsync">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private async Task OnWarehouseChangedAsync(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            await WarehouseState.SetWarehouseAsync(warehouseId);
            // Trigger an immediate alert refresh for the new warehouse
            await AlertService.RefreshNowAsync();
        }
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@using sv_85d58397bf1b4bfc875d87985ecfae63.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge position-relative">
    🔔
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge rounded-pill bg-danger position-absolute top-0 start-100 translate-middle">
            @AlertService.CurrentLowStockCount
        </span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

@page "/dashboard"
@using sv_85d58397bf1b4bfc875d87985ecfae63.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted">@WarehouseState.CurrentWarehouseName</h4>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(AlertService.CurrentLowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum levels
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseName</p>
                <p class="card-text text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="card-text text-muted">Polling while dashboard is visible</p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;

        // Start polling when the dashboard becomes visible
        AlertService.StartPolling();
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when the user leaves the dashboard
        AlertService.StopPolling();
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

